import {demoData as d} from '../mock-data.js';
import {getState,saveState,completeStep,saveField} from '../state.js';
import {page,status,actions,toast,setLoading,bindAutosave,escapeHtml,roadmap} from '../ui.js';

const routes={welcome:1,dashboard:3,start:4,identity:5,aadhaar:6,otp:7,'test-type':8,details:9,address:10,vehicle:11,declaration:12,'details-complete':13,documents:14,'documents-complete':15,review:16,payment:17,'payment-confirmation':18,'payment-success':19,preparation:20,tutorial:21,'tutorial-complete':22,slots:23,'slot-confirmed':24,roadmap:25,instructions:26,face:27,'face-failed':28,'face-success':29,test:30,passed:31,'not-passed':32,licence:33};

/** Renders a requested journey screen, falling back to the welcome screen. */
export function renderScreen(key){
  const step=routes[key]||1;
  const renderer=screens[key]||screens.welcome;
  document.querySelector('#main-content').innerHTML=renderer(step);
  document.title=`${screenTitles[key]||'Learner’s Licence Guide'} — Saathi`;
  bindCommon(step,key);
  bindScreen(key);
}

const screenTitles={welcome:'Driving licence services',dashboard:'Service dashboard',start:'Apply for a learner’s licence',identity:'Verify your identity',aadhaar:'Aadhaar verification',otp:'Verify mobile OTP','test-type':'Choose your test route',details:'Personal details',address:'Address details',vehicle:'Select vehicle class',declaration:'Declaration','details-complete':'Application details completed',documents:'Upload required documents','documents-complete':'Documents uploaded',review:'Review and submit',payment:'Pay application fee','payment-confirmation':'Application submitted','payment-success':'Payment successful',preparation:'Prepare for your test',tutorial:'Road safety tutorial','tutorial-complete':'Tutorial completed',slots:'Select test date and time','slot-confirmed':'Test slot confirmed',roadmap:'Your application roadmap',instructions:'Online test instructions',face:'Face authentication','face-failed':'Face authentication needs attention','face-success':'Face authentication successful',test:'Online learner’s licence test',passed:'You passed the test','not-passed':'Test not passed',licence:'Learner’s licence issued'};

/** Completes steps when forward links are activated. */
function bindCommon(step,key){
  document.querySelectorAll('[data-complete]').forEach(link=>link.addEventListener('click',()=>completeStep(Number(link.dataset.complete)||step)));
  if(step>=9&&key!=='roadmap')bindAutosave(saveField);
}

/** Connects the controls unique to the active screen. */
function bindScreen(key){
  const binders={welcome:bindWelcome,dashboard:bindDashboard,start:bindStart,identity:bindIdentity,otp:bindOtp,address:bindAddress,declaration:bindDeclaration,documents:bindDocuments,review:bindReview,payment:bindPayment,'payment-confirmation':bindPayment,'payment-success':bindPayment,preparation:bindPreparation,tutorial:bindTutorial,slots:bindSlots,'slot-confirmed':bindSlotConfirmed,face:bindFace,'face-failed':bindFace,test:bindTest,passed:bindPassed,'not-passed':bindRetake,licence:bindDownload};
  if(binders[key])binders[key]();
}

/** Standard card wrapper used for application forms. */
function card(content){return `<section class="card">${content}</section>`}

/** Four-step Application Details sub-stepper (Personal → Address → Vehicle → Declaration). */
function appStepper(current){
  const steps=[{n:1,label:'Personal Details',sub:'Your basic information'},{n:2,label:'Address Details',sub:'Your current address'},{n:3,label:'Select Vehicle Class',sub:'Choose vehicle type'},{n:4,label:'Declaration',sub:'Review &amp; confirm'}];
  return `<ol class="app-stepper" aria-label="Application details progress">${steps.map((s,i)=>{const cls=s.n<current?'complete':s.n===current?'current':'';const badge=s.n<current?'✓':s.n;const sub=s.n<current?'Completed':s.sub;const line=i<steps.length-1?`<span class="step-line ${s.n<current?'complete':''}" aria-hidden="true"></span>`:'';return `<li class="${cls}"><span class="step-badge">${badge}</span><div class="step-body"><strong>${s.label}</strong><span>${sub}</span></div></li>${line}`}).join('')}</ol>`;
}

/** Bottom action row used by the multi-step form pages. */
function formCta(back,next,continueId,continueLabel='Save &amp; Continue',completeStep){
  return `<div class="form-cta"><a class="button button-secondary" href="#/${back}">💾 Save &amp; Exit</a><a class="button button-primary" id="${continueId}" href="#/${next}"${completeStep?` data-complete="${completeStep}"`:''}>${continueLabel} →</a></div>`;
}

/** Shared breadcrumb used across the application-details sub-flow. */
function appBreadcrumb(current){return `<nav class="breadcrumb"><a href="#/dashboard">Home</a> › <a href="#/dashboard">Learner Licence</a> › <a href="#/start">Apply for Learner Licence</a> › <span>${current}</span></nav>`}

/** Six-step application-journey stepper used on payment and beyond. */
function journeyStepper(current,currentStatus='In Progress'){
  const steps=[{n:1,label:'Application Details',icon:'📄'},{n:2,label:'Upload Documents',icon:'📎'},{n:3,label:'Make Payment',icon:'₹'},{n:4,label:'Book Test Slot',icon:'📅'},{n:5,label:'Take Online Test',icon:'🖥️'},{n:6,label:"Learner’s Licence",icon:'🪪'}];
  return `<ol class="journey-stepper" aria-label="Application journey">${steps.map((s,i)=>{const complete=s.n<current;const active=s.n===current;const cls=complete?'complete':active?'current':'pending';const badge=complete?'✓':s.icon;const status=complete?'Completed':active?currentStatus:'Pending';const line=i<steps.length-1?`<span class="journey-line ${complete?'complete':''}" aria-hidden="true"></span>`:'';return `<li class="${cls}"><div class="journey-badge">${badge}</div><strong>${s.label}</strong><span class="journey-status">${status}</span></li>${line}`}).join('')}</ol>`;
}

/** Compact numbered card used across the Review & Submit page. */
function reviewSection(num,title,editHref,content){return `<div class="review-card"><div class="review-card-head"><h3>${num}. ${title}</h3>${editHref?`<a href="#/${editHref}" class="review-edit">✎ Edit</a>`:''}</div><div class="review-card-body">${content}</div></div>`}

/** Shared blue guidelines card used on Book Test Slot and Slot Confirmed pages. */
function guidelinesCard(){return `<div class="guidelines-card"><h2><span class="guidelines-icon">📋</span> Guidelines for Online Learner’s Licence Test</h2><div class="guidelines-grid"><ul class="guidelines-list"><li>Ensure you have a stable internet connection and a working webcam.</li><li>You will need a valid ID proof during the test.</li><li>The test contains multiple choice questions.</li><li>Passing marks: 16 out of 20 (80%).</li><li>You can take the test only after booking a slot.</li></ul><div class="guidelines-graphic" aria-hidden="true">🖥️</div></div></div>`}

/** Two-node stepper used across the face-authentication test flow. */
function testStepper(current){const steps=[{n:1,label:'Test Details'},{n:2,label:'Authentication'}];return `<ol class="test-stepper" aria-label="Test progress">${steps.map((s,i)=>{const complete=s.n<current;const cur=s.n===current;const cls=complete?'complete':cur?'current':'pending';const badge=complete?'✓':s.n;const line=i<steps.length-1?`<span class="test-line ${complete?'complete':''}" aria-hidden="true"></span>`:'';return `<li class="${cls}"><div class="test-badge">${badge}</div><strong>${s.label}</strong></li>${line}`}).join('')}</ol>`}

/** Standard user-triggered simulated network transition. */
function processLink(id,next,message,patch={}){
  const control=document.querySelector(`#${id}`);if(!control)return;
  control.addEventListener('click',event=>{event.preventDefault();setLoading(control,message);setTimeout(()=>{saveState(patch);window.location.hash=`#/${next}`},1700)});
}

const screens={
  welcome:()=>{const saved=getState().selectedState||'';const stateOptions=['Delhi','Haryana','Punjab','Uttar Pradesh','Maharashtra'];const optionsHtml=stateOptions.map(name=>`<option${saved===name?' selected':''}>${escapeHtml(name)}</option>`).join('');const resumeLink=saved?`<a class="button button-secondary" href="#/dashboard">Continue with ${escapeHtml(saved)}</a>`:'<span></span>';return `<section class="page"><div class="wrap"><div class="content-stack" style="max-width:44rem;margin-inline:auto"><header><p class="eyebrow">Driving Licence Services <span class="tag tag-demo">DEMO</span></p><h1>Select your state to get started</h1><p class="lede">Services and requirements vary by state. Choose where you live to see the route that applies to you. Your choice is saved on this device.</p></header>${card(`<h2>📍 Online services in this portal are available only for the States listed below</h2><div class="field"><label for="welcome-state-select">Please select the State from where the service is to be taken <span class="required">*</span></label><select id="welcome-state-select"><option value="">-- Select State --</option>${optionsHtml}</select><p class="hint">This demo journey is configured for Delhi.</p></div>${saved?`<p class="hint">Saved on this device: <strong>${escapeHtml(saved)}</strong></p>`:''}<div class="action-row">${resumeLink}<button class="button button-primary" id="welcome-continue" type="button">Continue →</button></div>`)}</div></div></section>`},

  dashboard:step=>{const saved=getState().selectedState||'Delhi';const services=[{icon:'🎓',title:'Apply for Learner Licence',desc:`Guided first-time application in ${saved}.`,href:'#/start',enabled:true},{icon:'🔄',title:'Apply for Driver Licence Renewal',desc:'Renew your driving licence before it expires.'},{icon:'📄',title:'Apply for Duplicate Driver Licence',desc:'Get a duplicate licence in case of loss, theft or damage.'},{icon:'🌐',title:'Apply for International Driver Licence',desc:'Get an International Driving Permit for overseas travel.'},{icon:'📋',title:'Driver Licence Extract',desc:'Get a digital copy of your driver licence details.'},{icon:'⚙️',title:'Driver Licence Services',desc:'Access various driver licence related services and updates.'}];return `<section class="dashboard"><div class="wrap"><section class="welcome-banner"><div class="welcome-content"><h1>Welcome to <span class="brand-name">Saathi</span></h1><p class="dept-name">Transport Department, ${escapeHtml(saved)}</p><p>Your one-stop solution for all Driving Licence related services. Apply, track, and manage your Driving Licence with ease.</p><div class="banner-actions"><a class="button button-primary" href="#/start" data-complete="3">Apply for Learner Licence</a><a class="button button-secondary" href="#" id="apply-dl-btn">Apply for Driving Licence</a></div></div><aside class="track-card"><h2>Track your application</h2><p>Enter your Application Number to check status</p><div class="track-row"><input type="text" id="track-input" placeholder="e.g. S1234567890123" aria-label="Application number"><button class="button button-primary" type="button" id="track-btn">Track Status</button></div><a href="#" class="hint" id="where-app-num">? Where is my application number?</a></aside></section><section class="services-section"><h2>Services at a glance</h2><p class="hint">Choose a service to get started</p><div class="services-grid">${services.map(s=>s.enabled?`<a class="service-card" href="${s.href}" data-complete="3"><div class="service-icon" aria-hidden="true">${s.icon}</div><strong>${escapeHtml(s.title)}</strong><span>${escapeHtml(s.desc)}</span></a>`:`<div class="service-card is-disabled" aria-disabled="true"><div class="service-icon" aria-hidden="true">${s.icon}</div><strong>${escapeHtml(s.title)}</strong><span>${escapeHtml(s.desc)}</span></div>`).join('')}</div></section><section class="info-grid"><div class="info-card info-card--tips"><h2>Before you start</h2><ul class="tick-list"><li>Keep scanned copies of required documents ready</li><li>Ensure you have a valid mobile number and email ID</li><li>Check the list of documents required for your service</li></ul><a href="#" class="info-link" id="doc-guidelines">View Document Guidelines ↗</a></div><div class="info-card info-card--help"><h2>Need help?</h2><p>Check our step-by-step guides and FAQs to help you through the process.</p><button class="button button-primary" type="button" id="help-center-btn">Visit Help Center</button></div><div class="info-card info-card--notif"><div class="notif-header"><h2>Notifications</h2><a href="#" id="view-all-notifs">View All</a></div><ul class="notif-list"><li><span>System maintenance scheduled on 28 Aug 2026 from 11:00 PM to 2:00 AM</span><time>20 Aug 2026</time></li><li><span>New service: License related services are now available online</span><time>18 Aug 2026</time></li><li><span>Important: Please update your mobile number for SMS alerts</span><time>15 Aug 2026</time></li></ul></div></section><p class="dashboard-footnote"><a href="#/welcome">Change selected state</a></p></div></section>`},

  start:step=>{const saved=getState().selectedState||'Delhi';const rtoMap={Delhi:['DL-11 Rohini Zonal Office','DL-13 West Delhi RTO','DL-05 South Delhi RTO'],Haryana:['HR-05 Karnal RTO','HR-01 Ambala RTO','HR-51 Faridabad RTO'],Punjab:['PB-10 Ludhiana RTO','PB-11 Patiala RTO','PB-02 Amritsar RTO'],'Uttar Pradesh':['UP-14 Ghaziabad RTO','UP-16 Noida RTO','UP-32 Lucknow RTO'],Maharashtra:['MH-01 Mumbai Central RTO','MH-02 Andheri RTO','MH-12 Pune RTO']};const rtoOptions=(rtoMap[saved]||rtoMap.Delhi).map(r=>`<option>${escapeHtml(r)}</option>`).join('');return `<section class="page"><div class="wrap"><nav class="breadcrumb"><a href="#/dashboard">Home</a> › Learner Licence › <span>Apply for Learner Licence</span></nav><div class="topic-hero"><div><h1>Apply for Learner Licence</h1><p class="lede">Begin your journey to becoming a responsible driver. We’ll guide you through a simple, step-by-step process.</p></div><div class="topic-hero-illustration" aria-hidden="true">🚗</div></div><div class="stacked-card"><div class="section-block rto-block"><div class="section-heading"><div class="section-icon">📍</div><div><h2>Select your RTO</h2><p class="hint">Select the RTO where you want to apply for your Learner Licence.</p></div></div><div class="rto-fields"><div class="field"><label>Selected State</label><div class="chip-input"><span>${escapeHtml(saved)}</span><span class="check" aria-hidden="true">✓</span></div></div><div class="field"><label for="rto-select">Select RTO <span class="required">*</span></label><select id="rto-select"><option value="">-- Select RTO --</option>${rtoOptions}</select></div></div><div class="rto-help"><p class="hint">Not sure which RTO to choose?</p><a href="#" class="info-link" id="find-rto">Find your RTO ↗</a></div></div><div class="section-block"><div class="row-space-between"><div><h2>Before you start</h2><p class="hint">Keep the following documents and details ready.</p></div><a href="#/documents" class="info-link">View complete requirements ↗</a></div><div class="doc-row"><span class="doc-item"><span class="doc-icon">📇</span>Identity Proof</span><span class="doc-item"><span class="doc-icon">📅</span>Age Proof</span><span class="doc-item"><span class="doc-icon">📍</span>Address Proof</span><span class="doc-item"><span class="doc-icon">🖼</span>Recent Photograph</span><span class="doc-item"><span class="doc-icon">✏️</span>Signature</span></div></div><div class="section-block"><div><h2>What happens next?</h2><p class="hint">Once you continue, you’ll follow these simple steps.</p></div><div class="steps-row"><div class="step-item"><span class="step-num">1</span><strong>Fill application details</strong></div><span class="step-arrow" aria-hidden="true">›</span><div class="step-item"><span class="step-num">2</span><strong>Upload documents</strong></div><span class="step-arrow" aria-hidden="true">›</span><div class="step-item"><span class="step-num">3</span><strong>Pay &amp; complete your application</strong></div></div></div><div class="cta-block"><div class="cta-copy"><span class="cta-icon" aria-hidden="true">📋</span>Click Continue to apply for Learner Licence.</div><a class="button button-primary" href="#/identity" id="start-continue" data-complete="4">Continue →</a></div></div></div></section>`},

  identity:step=>`<section class="page"><div class="wrap"><nav class="breadcrumb"><a href="#/dashboard">Home</a> › Learner Licence › <a href="#/start">Apply for Learner Licence</a> › <span>Choose Verification</span></nav><div class="topic-hero"><div><h1>Choose how you’d like to verify your identity</h1></div><div class="topic-hero-illustration" aria-hidden="true">🚙 🪪</div></div><div class="stacked-card"><div class="section-block"><div class="row-space-between"><h2>Select a verification method</h2><a href="#" class="info-link" id="learn-more-verif">Learn more about verification methods ↗</a></div><div class="verif-methods"><label class="verif-card"><input type="radio" name="identity" value="aadhaar" checked><div class="verif-card-head"><div class="verif-icon">🔐</div><div><strong>Aadhaar e-KYC</strong><p class="hint">Verify your identity using Aadhaar.</p></div></div><div class="verif-sub"><strong>Choose your test mode later</strong><span>You can choose between an online or physical LL test in the next step.</span></div></label><label class="verif-card"><input type="radio" name="identity" value="offline"><div class="verif-card-head"><div class="verif-icon">📄</div><div><strong>Offline Verification Method</strong><p class="hint">Continue without Aadhaar e-KYC.</p></div></div><div class="verif-sub"><strong>LL test at RTO</strong><span>You’ll need to visit the RTO to take your Learner Licence test.</span></div></label></div><div class="info-banner"><span class="info-banner-icon" aria-hidden="true">ℹ</span>You can still access all services. Some steps may vary based on the option you choose.</div></div><div class="cta-block"><a class="button button-secondary" href="#/start">← Back</a><a class="button button-primary" href="#/aadhaar" id="identity-continue" data-complete="5">Continue →</a></div></div></div></section>`,

  aadhaar:step=>`<section class="page"><div class="wrap"><nav class="breadcrumb"><a href="#/dashboard">Home</a> › Learner Licence › <a href="#/start">Apply for Learner Licence</a> › <a href="#/identity">Choose Verification</a> › <span>Aadhaar Verification</span></nav><div class="topic-hero"><div><h1>Aadhaar Verification</h1><p class="lede">Enter your Aadhaar number to proceed with identity verification.</p></div><div class="topic-hero-illustration" aria-hidden="true">🔐 📱</div></div><div class="stacked-card"><div class="section-block"><h2 class="step-heading">Enter Aadhaar Number</h2><div class="field"><label for="aadhaar-number">Aadhaar Number</label><input id="aadhaar-number" placeholder="Enter 12 digit Aadhaar number" inputmode="numeric" value="${d.applicant.aadhaarDemo}"></div><div class="info-banner"><span class="info-banner-icon" aria-hidden="true">ℹ</span>Your Aadhaar details will be used for identity verification only and will be kept secure.</div></div><div class="cta-block"><a class="button button-secondary" href="#/identity">← Back</a><a class="button button-primary" href="#/otp" id="aadhaar-continue" data-complete="6">Verify Aadhaar →</a></div></div></div></section>`,

  otp:step=>`<section class="page"><div class="wrap"><nav class="breadcrumb"><a href="#/dashboard">Home</a> › Learner Licence › <a href="#/start">Apply for Learner Licence</a> › <a href="#/identity">Choose Verification</a> › <span>Aadhaar Verification</span></nav><div class="topic-hero"><div><h1>Aadhaar Verification</h1><p class="lede">Enter your Aadhaar number and verify using the OTP sent to your registered mobile number.</p></div><div class="topic-hero-illustration" aria-hidden="true">🔐 📱</div></div><div class="stacked-card"><div class="aadhaar-steps"><div class="aadhaar-step"><h2 class="step-heading">Step 1: Enter Aadhaar Number</h2><div class="field"><label for="aadhaar-number-filled">Aadhaar Number</label><input id="aadhaar-number-filled" value="${d.applicant.aadhaarDemo}" readonly></div><div class="info-banner"><span class="info-banner-icon" aria-hidden="true">ℹ</span>Your Aadhaar details will be used for identity verification only and will be kept secure.</div></div><div class="aadhaar-step"><h2 class="step-heading">Step 2: Verify with OTP</h2><p class="hint">OTP sent to your registered mobile number</p><p class="mobile-line"><strong>${d.applicant.mobile}</strong> <a href="#" id="change-mobile">Change</a></p><label class="otp-label">Enter OTP</label><div class="otp-boxes" id="otp-boxes">${[0,1,2,3,4,5].map(i=>`<input type="text" maxlength="1" inputmode="numeric" data-otp-index="${i}" value="${d.applicant.otp[i]}" aria-label="OTP digit ${i+1}">`).join('')}</div><p class="hint">Didn’t receive OTP? <a href="#" id="resend-otp">Resend OTP</a> in <span class="otp-timer" id="otp-timer">00:45</span></p></div></div><div class="cta-block"><a class="button button-secondary" href="#/aadhaar">← Back</a><a class="button button-primary" href="#/test-type" id="otp-continue" data-complete="7">Verify &amp; Continue →</a></div></div></div></section>`,

  'test-type':step=>`<section class="page"><div class="wrap"><nav class="breadcrumb"><a href="#/dashboard">Home</a> › <a href="#/dashboard">Learner Licence</a> › <a href="#/start">Apply for Learner Licence</a> › <span>Choose Test Type</span></nav><div class="topic-hero"><div><h1>Since your identity is eKYC verified, you can choose your Learner’s Licence test type</h1><p class="lede">Choose how you want to take your Learner’s Licence test. You can change this later if needed.</p></div><div class="topic-hero-illustration" aria-hidden="true">🚗</div></div><div class="verif-methods"><label class="verif-card"><input type="radio" name="test-mode" value="online" checked><div class="verif-card-head"><div class="verif-icon">🖥️</div><div><strong>Online Learner’s Licence Test</strong><span class="pill pill-success">Online from anywhere</span></div></div><p class="verif-desc">Take the LL test online using your device with a webcam. No need to visit the RTO for the test.</p></label><label class="verif-card"><input type="radio" name="test-mode" value="rto"><div class="verif-card-head"><div class="verif-icon">🏢</div><div><strong>Physical RTO Learner’s Licence Test</strong><span class="pill pill-muted">At RTO</span></div></div><p class="verif-desc">Visit the RTO and take the LL test in person on the test day.</p></label></div><div class="stacked-card faceless-steps-card"><div class="section-block"><h2 class="step-heading"><span class="verif-icon">🖥️</span> Faceless Learner’s Licence Steps</h2><ol class="flow-steps">${['📄|Application Details','📎|Upload Documents','💵|Make Payment','▶️|Watch Road Safety Video','📅|Book Test Slot','🖥️|Take Online Test','🪪|Learner’s Licence Issued'].map(s=>{const[icon,label]=s.split('|');return `<li><div class="flow-icon">${icon}</div><span>${label}</span></li>`}).join('')}</ol></div></div><div class="form-cta"><a class="button button-secondary" href="#/otp">← Back</a><a class="button button-primary" href="#/details" id="test-type-continue" data-complete="8">Continue to fill Application Details →</a></div></div></section>`,

  details:step=>{const state=getState();const f=state.form||{};const val=(name,fallback='')=>escapeHtml(f[name]!==undefined?f[name]:fallback);return `<section class="page"><div class="wrap">${appBreadcrumb('Application Details')}${appStepper(1)}<div class="stacked-card app-form-card"><div class="form-header"><div><h2 class="step-heading">Personal Details</h2><p class="hint">Please provide your personal information as per your identity proof.</p></div><div class="mandatory-tag"><span aria-hidden="true">ℹ</span> All fields marked with <span class="required">*</span> are mandatory</div></div><div class="section-block"><label class="composite-label">Name of the Applicant<span class="required">*</span></label><div class="triple-grid"><input placeholder="FIRST NAME" name="firstName" data-save value="${val('firstName',d.applicant.firstName)}"><input placeholder="MIDDLE NAME" name="middleName" data-save value="${val('middleName')}"><input placeholder="LAST NAME" name="lastName" data-save value="${val('lastName',d.applicant.lastName)}"></div><p class="hint hint-danger">Note: If Middle name is more than 6 characters, then middle name could be entered in either in First Name or Last Name and will be printed on Driving Licence.</p></div><div class="section-block"><label class="composite-label">Relation<span class="required">*</span></label><div class="quad-grid"><select name="relation" data-save><option value="">Select</option><option>Father</option><option>Mother</option><option>Guardian</option></select><input placeholder="FIRST NAME" name="relFirst" data-save value="${val('relFirst')}"><input placeholder="MIDDLE NAME" name="relMiddle" data-save value="${val('relMiddle')}"><input placeholder="LAST NAME" name="relLast" data-save value="${val('relLast')}"></div></div><div class="section-block"><div class="field"><label>Full Name as per Records<span class="required">*</span></label><input placeholder="NEW FULL NAME" name="fullName" data-save value="${val('fullName',d.applicant.name)}"></div></div><div class="section-block form-grid-3"><div class="field"><label>Gender<span class="required">*</span></label><div class="radio-inline"><label><input type="radio" name="genderR" value="Male" checked> Male</label><label><input type="radio" name="genderR" value="Female"> Female</label><label><input type="radio" name="genderR" value="Trans"> Trans Gender</label></div></div><div class="field"><label>Date of Birth<span class="required">*</span></label><input type="text" placeholder="DD-MM-YYYY" name="dob" data-save value="${val('dob',d.applicant.dob)}"></div><div class="field"><label>Age</label><div class="chip-input chip-age"><span>21</span><span>Yrs</span></div></div></div><div class="section-block form-grid-2"><div class="field"><label>Place of Birth</label><input placeholder="PLACE OF BIRTH" name="birthPlace" data-save value="${val('birthPlace')}"></div><div class="field"><label>Country of Birth<span class="required">*</span></label><select name="birthCountry" data-save><option>INDIA</option></select></div></div><div class="section-block form-grid-2"><div class="field"><label>Qualification<span class="required">*</span></label><select name="qualification" data-save><option value="">Select</option><option>Below 10th</option><option>10th Passed</option><option>12th Passed</option><option>Graduate</option><option>Post Graduate</option></select></div><div class="field"><label>Blood Group</label><select name="bloodGroup" data-save><option>Unknown</option><option>A+</option><option>B+</option><option>O+</option><option>AB+</option></select></div></div><div class="section-block form-grid-2"><div class="field"><label>Landline Number</label><input placeholder="EX:04023659856" name="landline" data-save value="${val('landline')}"></div><div class="field"><label>Email Id</label><input placeholder="Ex:abc@xyz.com" name="email" data-save value="${val('email',d.applicant.email)}"></div></div><div class="section-block form-grid-2"><div class="field"><label>Applicants Mobile Number<span class="required">*</span></label><div class="prefix-input"><span class="prefix">+91</span><input name="mobile" data-save value="${val('mobile','9899420024')}" inputmode="numeric"></div></div><div class="field"><label>Emergency Mobile Number</label><div class="prefix-input"><span class="prefix">+91</span><input placeholder="ALTERNATE MOBILE NUMBER" name="mobileAlt" data-save value="${val('mobileAlt')}" inputmode="numeric"></div></div></div><div class="section-block form-grid-2"><div class="field"><label>Identification Marks 1</label><input placeholder="SCAR ON HEAD, MOLE ON" name="mark1" data-save value="${val('mark1')}"></div><div class="field"><label>Identification Marks 2.</label><input placeholder="SCAR ON HEAD, MOLE ON" name="mark2" data-save value="${val('mark2')}"></div></div><div class="section-block"><div class="info-banner"><span class="info-banner-icon" aria-hidden="true">🛡</span><div><strong>Please Note</strong><br>Information provided must match your identity proof. You will not be able to change these details later.</div></div></div>${formCta('dashboard','address','details-continue','Save &amp; Continue',9)}</div></div></section>`},

  address:step=>{const state=getState();const f=state.form||{};const saved=state.selectedState||'Delhi';const val=(name,fallback='')=>escapeHtml(f[name]!==undefined?f[name]:fallback);const stateOptions=['Delhi','Haryana','Punjab','Uttar Pradesh','Maharashtra'].map(s=>`<option${s===saved?' selected':''}>${escapeHtml(s)}</option>`).join('');return `<section class="page"><div class="wrap">${appBreadcrumb('Application Details')}${appStepper(2)}<div class="stacked-card app-form-card"><div class="form-header"><div><h2 class="step-heading">Address Details</h2><p class="hint">Please provide your current and permanent address.</p></div><div class="mandatory-tag"><span aria-hidden="true">ℹ</span> All fields marked with <span class="required">*</span> are mandatory</div></div><div class="address-columns"><div class="address-column"><div class="column-title"><h3>📍 Present Address</h3></div><div class="sub-section-title">Location</div><div class="field-quad"><div class="field"><label>State<span class="required">*</span></label><select name="preState" data-save>${stateOptions}</select></div><div class="field"><label>District<span class="required">*</span></label><select name="preDistrict" data-save><option>Select District</option><option>North West Delhi</option><option>North Delhi</option><option>South Delhi</option></select></div><div class="field"><label>Tehsil<span class="required">*</span></label><select name="preTehsil" data-save><option>Select Tehsil</option><option>Rohini</option><option>Narela</option></select></div><div class="field"><label>Village / Town<span class="required">*</span></label><select name="preTown" data-save><option>Select Village / Town</option><option>Rohini</option></select></div></div><div class="sub-section-title">Address Details</div><div class="field-stack"><div class="field"><label>House / Door / Flat No.<span class="required">*</span></label><input placeholder="Enter House / Door / Flat No." name="preHouse" data-save value="${val('preHouse','42, Sample Residency')}"><p class="hint mini">e.g. 1234, Flat 101</p></div><div class="field"><label>Street / Locality / Police Station<span class="required">*</span></label><input placeholder="Enter Street / Locality / Police Station" name="preStreet" data-save value="${val('preStreet')}"><p class="hint mini">e.g. MG Road, Near Police Station</p></div><div class="field"><label>Location / Area<span class="required">*</span></label><input placeholder="Enter Location / Area" name="preArea" data-save value="${val('preArea','Rohini')}"><p class="hint mini">e.g. Near City Center</p></div><div class="field"><label>Pincode<span class="required">*</span></label><input placeholder="Enter Pincode" name="prePincode" data-save value="${val('prePincode','110085')}" inputmode="numeric"><p class="hint mini">6-digit pincode</p></div><div class="field"><label>Duration of stay at present address<span class="required">*</span></label><select name="preDuration" data-save><option>Select Duration</option><option>Less than 1 year</option><option>1-3 years</option><option>3-5 years</option><option>More than 5 years</option></select></div></div></div><div class="address-column"><div class="column-title"><h3>📍 Permanent Address</h3><label class="checkbox-inline"><input type="checkbox" id="same-address"> Same as present address</label></div><div class="sub-section-title">Location</div><div class="field-quad"><div class="field"><label>State<span class="required">*</span></label><select name="permState" data-save>${stateOptions}</select></div><div class="field"><label>District<span class="required">*</span></label><select name="permDistrict" data-save><option>Select District</option></select></div><div class="field"><label>Tehsil<span class="required">*</span></label><select name="permTehsil" data-save><option>Select Tehsil</option></select></div><div class="field"><label>Village / Town<span class="required">*</span></label><select name="permTown" data-save><option>Select Village / Town</option></select></div></div><div class="sub-section-title">Address Details</div><div class="field-stack"><div class="field"><label>House / Door / Flat No.<span class="required">*</span></label><input placeholder="Enter House / Door / Flat No." name="permHouse" data-save value="${val('permHouse')}"><p class="hint mini">e.g. 1234, Flat 101</p></div><div class="field"><label>Street / Locality / Police Station<span class="required">*</span></label><input placeholder="Enter Street / Locality / Police Station" name="permStreet" data-save value="${val('permStreet')}"><p class="hint mini">e.g. MG Road, Near Police Station</p></div><div class="field"><label>Location / Area<span class="required">*</span></label><input placeholder="Enter Location / Area" name="permArea" data-save value="${val('permArea')}"><p class="hint mini">e.g. Near City Center</p></div><div class="field"><label>Pincode<span class="required">*</span></label><input placeholder="Enter Pincode" name="permPincode" data-save value="${val('permPincode')}" inputmode="numeric"><p class="hint mini">6-digit pincode</p></div></div></div></div><div class="section-block"><div class="column-title"><h3>📍 Your RTO Office</h3></div><p class="hint">Select office for driving test</p><div class="rto-map-block"><div class="rto-select-side"><select name="rtoOffice" data-save><option>${escapeHtml(d.application.rto)} - Approx 5.2 km away</option><option>DL-05 South Delhi - Approx 12.4 km away</option><option>DL-13 West Delhi - Approx 8.1 km away</option></select><p class="hint hint-info"><span aria-hidden="true">ℹ</span> Based on your residential address provided above.</p></div><div class="rto-map" aria-hidden="true">🗺️</div></div></div>${formCta('details','vehicle','address-continue','Save &amp; Continue',10)}</div></div></section>`},

  vehicle:step=>{const state=getState();const chosen=state.form&&state.form.vehicleClass||'MCWOG';return `<section class="page"><div class="wrap">${appBreadcrumb('Application Details')}${appStepper(3)}<div class="stacked-card app-form-card"><div class="form-header"><div><h2 class="step-heading">Select Vehicle Class</h2><p class="hint">Choose the type of vehicle you want to learn to drive.</p></div><div class="mandatory-tag"><span aria-hidden="true">ℹ</span> You can select only one vehicle class.</div></div><div class="section-block"><div class="vehicle-grid">${[{code:'MCWG',name:'Motorcycle with Gear',icon:'🏍️',desc:'Two-wheelers with a manual gearbox (e.g., standard bikes). Also covers scooters.'},{code:'LMV',name:'Light Motor Vehicle',icon:'🚗',desc:'Cars, jeeps, and small vans for personal use.'},{code:'MCWOG',name:'Motorcycle w/o Gear',icon:'🛵',desc:'Scooters and mopeds without manual gears.'},{code:'HMV',name:'Heavy Motor Vehicle',icon:'🚚',desc:'Trucks, buses, and other heavy commercial vehicles.',disabled:true}].map(v=>v.disabled?`<div class="vehicle-card is-disabled" aria-disabled="true"><span class="warn-tag">Requires LMV First</span><div class="vehicle-icon">${v.icon}</div><strong>${v.name}</strong><p>${v.desc}</p></div>`:`<label class="vehicle-card"><input type="radio" name="vehicleClass" value="${v.code}" data-save${chosen===v.code?' checked':''}><div class="vehicle-icon">${v.icon}</div><strong>${v.name}</strong><p>${v.desc}</p><span class="tag tag-neutral">${v.code}</span></label>`).join('')}</div></div>${formCta('address','declaration','vehicle-continue','Save &amp; Continue',11)}</div></div></section>`},

  declaration:step=>`<section class="page"><div class="wrap">${appBreadcrumb('Application Details')}${appStepper(4)}<div class="stacked-card app-form-card"><div class="form-header"><div><h2 class="step-heading">Declaration</h2><p class="hint">Please review the declaration and confirm to proceed.</p></div></div><div class="section-block"><div class="info-banner info-banner-plain">Please read all the declarations carefully before proceeding.</div></div><div class="section-block"><div class="declaration-row"><div><h3>Fill-up Form1 details before submitting the application</h3><p class="hint">You must fill out Form1 (Self-Declaration) before final submission of your application.</p></div><button class="button button-secondary" id="form1-btn" type="button">Click here for Self-Declaration (Form1)</button></div></div><div class="section-block"><div class="declaration-row"><h3>I am willing to donate my organs, in case of accidental death?</h3><div class="radio-inline"><label><input type="radio" name="organs" value="yes"> Yes</label><label><input type="radio" name="organs" value="no" checked> No</label></div></div></div><div class="section-block"><h3>Declaration of Fitness</h3><label class="declaration-check"><input type="checkbox" id="fitness-check"><span>I hereby declare that to the best of my knowledge and belief, I am physically fit to hold a driving license and I do not suffer from any disease or disability that makes my driving dangerous to the public.</span></label></div>${formCta('vehicle','details-complete','declaration-continue','Save &amp; Continue',12)}</div></div></section>`,

  'details-complete':step=>page({step,title:'Application details completed',intro:'Your information has been saved to this device and is ready for document upload.',content:`${status('success','Completed','Application details saved',`Demo application number: ${d.application.number}. No action is needed on this step.`)}${card(`<h2>What was recorded</h2><div class="summary-grid"><p><strong>Identity</strong><br>${d.applicant.name}</p><p><strong>RTO</strong><br>${d.application.rto}</p><p><strong>Vehicle class</strong><br>${d.application.vehicle}</p></div>`)}${actions('declaration','documents','Upload documents','details-done')}`}),

  documents:step=>{const docs=[{name:'Proof of Address',desc:'Aadhaar Card, Passport, or Utility Bill',icon:'🏠',type:'Aadhaar Card',number:'451653',issuedBy:'UIDAI',issueDate:'12/05/2024',contact:'9876543210',file:'aadhaar_card.pdf'},{name:'Proof of Age',desc:'Birth Certificate, 10th Marksheet, or Passport',icon:'📄',file:'birth_certificate.pdf'},{name:'Passport Size Photograph',desc:'Recent photograph with white background',icon:'🖼️',file:'my_photo.jpg'},{name:'Scanned Signature',desc:'Signature on white paper in black ink',icon:'✎',file:'signature.jpg'}];return `<section class="page"><div class="wrap"><nav class="breadcrumb"><a href="#/dashboard">Home</a> › <a href="#/dashboard">Learner Licence</a> › <a href="#/start">Apply for Learner Licence</a></nav><div class="page-header-block"><h1>Upload Documents</h1><div class="app-num-chip">Application Number: <strong>${d.application.number}</strong></div></div><h2 class="section-title">Required Documents (${docs.length}/${docs.length})</h2><div class="doc-cards">${docs.map((doc,i)=>`<div class="doc-card${i===0?' is-expanded':''}" data-doc-card><div class="doc-card-head"><div class="doc-icon-square">${doc.icon}</div><div class="doc-title"><strong>${escapeHtml(doc.name)}</strong><span class="hint">${escapeHtml(doc.desc)}</span></div><span class="pill pill-uploaded">✓ Uploaded</span><div class="doc-actions"><button class="icon-btn" type="button" aria-label="Preview">👁</button><button class="icon-btn danger" type="button" aria-label="Remove">🗑</button><button class="icon-btn toggle-btn" type="button" aria-label="Toggle details" data-doc-toggle>▾</button></div></div>${doc.type?`<div class="doc-details"><div class="doc-details-grid"><div><span class="hint">Document Type</span><strong>${escapeHtml(doc.type)}</strong></div><div><span class="hint">Document Number</span><strong>${escapeHtml(doc.number)}</strong></div><div><span class="hint">Issued By</span><strong>${escapeHtml(doc.issuedBy)}</strong></div><div><span class="hint">Issue Date</span><strong>${escapeHtml(doc.issueDate)}</strong></div><div><span class="hint">Contact Number</span><strong>${escapeHtml(doc.contact)}</strong></div></div><div class="doc-details-cta"><button class="button button-secondary" type="button" data-edit-doc>✎ Edit Details</button></div></div>`:''}</div>`).join('')}</div><div class="info-banner info-banner-plain"><span class="info-banner-icon" aria-hidden="true">ℹ</span><div><strong>Note:</strong> All documents will be verified by the RTO. Incorrect or unclear documents may lead to rejection of your application.</div></div>${formCta('details-complete','review','documents-continue','Save &amp; Continue',15)}</div></section>`},

  'documents-complete':step=>page({step,title:'All documents are ready',intro:'Every required file passed the demo checks and has been linked to your saved application.',content:`${status('success','Completed','4 of 4 documents recorded','No action is required. You can preview the synthetic entries below or continue to review.')} ${card(`<div class="document-list">${d.documents.map(doc=>`<div class="document-row"><div><strong>${doc.name}</strong><div class="hint">${doc.file}</div></div><span class="tag is-success">✓ Ready</span></div>`).join('')}</div>`)}${actions('documents','review','Review application','documents-done')}`}),

  review:step=>{const addressLine=`${d.address.line1}, ${d.address.locality}, ${d.address.district}, ${d.address.pincode}`;return `<section class="page"><div class="wrap"><nav class="breadcrumb"><a href="#/dashboard">Home</a> › <a href="#/dashboard">Learner Licence</a> › <a href="#/start">Apply for Learner Licence</a> › <span>Make Payment</span></nav><div class="page-header-block"><h1>Review &amp; Submit</h1><div class="app-num-chip">Application Number: <strong>${d.application.number}</strong></div></div><div class="info-banner info-banner-plain"><span class="info-banner-icon" aria-hidden="true">ℹ</span>Please review all details carefully before submitting. You will not be able to edit after submission.</div><ol class="mini-stepper"><li class="complete"><div class="mini-badge">📄</div><strong>1 Review all details</strong><span>Verify your personal, address, selected vehicle class and uploaded documents.</span></li><li class="current"><div class="mini-badge">₹</div><strong>2 See fee breakdowns</strong><span>View the complete fee details before proceeding to payment.</span></li><li><div class="mini-badge">✓</div><strong>3 Confirm declaration</strong><span>Read and accept the declaration to submit your application.</span></li></ol><div class="review-sections">${reviewSection('1','Personal Details','details',`<div class="review-grid"><div><span class="hint">Full Name</span><strong>${escapeHtml(d.applicant.name)}</strong></div><div><span class="hint">Date of Birth</span><strong>${escapeHtml(d.applicant.dob)}</strong></div><div><span class="hint">Gender</span><strong>${escapeHtml(d.applicant.gender)}</strong></div><div><span class="hint">Blood Group</span><strong>O+</strong></div><div><span class="hint">Father’s / Guardian’s Name</span><strong>${escapeHtml(d.applicant.fatherName)}</strong></div><div><span class="hint">Mobile Number</span><strong>${escapeHtml(d.applicant.mobile)}</strong></div><div><span class="hint">Email ID</span><strong>${escapeHtml(d.applicant.email)}</strong></div><div><span class="hint">Nationality</span><strong>Indian</strong></div></div>`)}${reviewSection('2','Address Details','address',`<div class="review-grid two-col"><div><span class="hint">Permanent Address</span><strong>${escapeHtml(addressLine)}</strong></div><div><span class="hint">Correspondence Address <span class="pill pill-success">Same as permanent</span></span><strong>${escapeHtml(addressLine)}</strong></div></div>`)}${reviewSection('3','Selected Vehicle Class','vehicle',`<strong>${escapeHtml(d.application.vehicle)} (MCWOG)</strong><div class="hint">Validity: 6 Months</div>`)}${reviewSection('4','Uploaded Documents (4/4)','documents',`<div class="table-scroll"><table class="review-table"><thead><tr><th>Document</th><th>File Name</th><th>Status</th><th>Action</th></tr></thead><tbody>${d.documents.map(doc=>`<tr><td>${escapeHtml(doc.name)}</td><td>${escapeHtml(doc.file)}</td><td><span class="pill pill-uploaded">✓ Uploaded</span></td><td><span class="doc-actions-mini"><button class="icon-btn" type="button" aria-label="Preview">👁</button><button class="icon-btn danger" type="button" aria-label="Remove">🗑</button></span></td></tr>`).join('')}</tbody></table></div>`)}${reviewSection('5','Fee Breakdown','payment',`<div class="fee-lines"><div class="fee-line"><span>Learner Licence Fee</span><strong>₹150.00</strong></div><div class="fee-line"><span>Smart Card Fee</span><strong>₹50.00</strong></div><div class="fee-line total"><span>Total Amount <span class="hint">(Inclusive of all taxes)</span></span><strong>₹200.00</strong></div></div><p class="hint hint-info"><span aria-hidden="true">ℹ</span> The fee once paid is non-refundable.</p>`)}${reviewSection('6','Declaration','',`<label class="declaration-check"><input type="checkbox" id="review-declaration"><span>I hereby declare that the particulars given above are true to the best of my knowledge and belief and I undertake that I shall not indulge in any malpractice. I am aware that furnishing of any false information or suppression of any material fact may lead to rejection of my application or cancellation of the licence at any stage.</span></label>`)}</div>${formCta('documents','payment','review-submit','Confirm &amp; Submit Application',16)}</div></section>`},

  payment:step=>`<section class="page"><div class="wrap"><nav class="breadcrumb"><a href="#/dashboard">Home</a> › <a href="#/dashboard">Learner Licence</a> › <a href="#/start">Apply for Learner Licence</a></nav><div class="page-header-block"><h1>Application for Learner’s Licence</h1><div class="app-num-chip">Application Number: <strong>${d.application.number}</strong></div></div>${journeyStepper(3,'In Progress')}<div class="info-banner info-banner-plain"><span class="info-banner-icon" aria-hidden="true">ℹ</span>Almost there! Please complete the payment to submit your application.</div><div class="payment-heading"><h2>Complete Payment</h2><p class="hint">Review your fee breakdown and securely complete your transaction.</p></div><div class="payment-columns"><div class="payment-card fee-card"><h3><span class="verif-icon">🧾</span>Fee Breakdown</h3><div class="fee-lines"><div class="fee-line"><span>Application Fee</span><strong>₹200.00</strong></div><div class="fee-line"><span>Service Charge</span><strong>₹50.00</strong></div><div class="fee-line"><span>Processing Fee</span><strong>₹25.00</strong></div></div><div class="total-card"><div class="hint">Total Amount <span>(Inclusive of all taxes)</span></div><div class="total-amount">${d.payment.total}</div></div><p class="hint hint-info"><span aria-hidden="true">ℹ</span> The fee once paid is non-refundable.</p><div class="secure-note"><strong>Secure Payment Gateway</strong><span>Your payment details are safe and encrypted.</span></div></div><div class="payment-card method-card"><h3><span class="verif-icon">💳</span>Select Payment Method</h3><div class="method-list"><label class="method-card-item"><input type="radio" name="payMethod" value="upi" checked><div><strong>UPI</strong><span class="hint">Google Pay, PhonePe, Paytm</span></div><span class="method-icon" aria-hidden="true">▦</span></label><label class="method-card-item"><input type="radio" name="payMethod" value="card"><div><strong>Debit / Credit Card</strong><span class="hint">Visa, MasterCard, RuPay</span></div><span class="method-icon" aria-hidden="true">💳</span></label><label class="method-card-item"><input type="radio" name="payMethod" value="netbanking"><div><strong>Net Banking</strong><span class="hint">All major Indian banks</span></div><span class="method-icon" aria-hidden="true">🏦</span></label></div><div class="method-actions"><a class="button button-secondary" href="#/review">Cancel</a><a class="button button-primary" href="#/payment-success" id="pay-button" data-complete="17">Confirm &amp; Pay ${d.payment.total} 🔒</a></div></div></div><div class="info-banner info-banner-plain"><span class="info-banner-icon" aria-hidden="true">ℹ</span><div><strong>Note:</strong> After successful payment, you will be able to book your test slot.</div></div></div></section>`,

  'payment-confirmation':step=>page({step,title:'Application submitted',intro:'Your application details are locked and the simulated payment is ready for approval.',content:`${status('warning','Action required','Confirm the demo payment',`Amount: ${d.payment.total}. Nothing has been charged yet.`)}${card(`<h2>Payment summary</h2><p><strong>Application:</strong> ${d.application.number}</p><p><strong>Method:</strong> ${d.payment.method}</p><p><strong>Total:</strong> ${d.payment.total}</p>`)}${actions('payment','payment-success','Confirm payment','confirm-payment')}`}),

  'payment-success':step=>`<section class="page"><div class="wrap"><nav class="breadcrumb"><a href="#/dashboard">Home</a> › <a href="#/dashboard">Learner Licence</a> › <a href="#/start">Apply for Learner Licence</a></nav><div class="page-header-block header-with-chip"><h1>Application for Learner’s Licence</h1><div class="app-num-chip">Application Number: <strong>${d.application.number}</strong></div></div>${journeyStepper(4,'Pending')}<div class="success-card"><div class="success-check">✓</div><h1>Transaction Successful!</h1><p class="lede">Your payment has been received successfully.</p><div class="app-num-chip large">Application Number: <strong>${d.application.number}</strong></div></div><div class="review-card"><div class="review-card-head"><h3>Payment Summary</h3></div><div class="review-card-body"><div class="review-grid four-col"><div><span class="hint">Transaction ID</span><strong>${escapeHtml(d.payment.transaction)}</strong></div><div><span class="hint">Payment Mode</span><strong>UPI (Google Pay)</strong><span class="pill pill-success">Paid</span></div><div><span class="hint">Payment Date &amp; Time</span><strong>${escapeHtml(d.payment.date)}</strong></div><div class="text-right"><span class="hint">Total Amount Paid</span><strong class="paid-amount">${d.payment.total}</strong><span class="hint">(Inclusive of all taxes)</span></div></div></div></div><div class="review-card"><div class="review-card-head"><h3>What’s Next?</h3></div><div class="review-card-body"><div class="whats-next-grid"><div class="whats-next-item"><div class="whats-next-icon">📅</div><div><strong>Book your test slot</strong><span class="hint">Schedule your Learner’s Licence test at your preferred RTO.</span></div></div><div class="whats-next-item"><div class="whats-next-icon">🖥️</div><div><strong>Take the Online Test</strong><span class="hint">Appear for the online test on the scheduled date and time.</span></div></div><div class="whats-next-item"><div class="whats-next-icon">🪪</div><div><strong>Get your Learner’s Licence</strong><span class="hint">Once you pass the test, your Learner’s Licence will be issued.</span></div></div></div></div></div><div class="form-cta"><button class="button button-secondary" type="button" id="print-receipt">🖨 Print Receipt</button><a class="button button-primary" href="#/preparation" id="payment-done" data-complete="19">📅 Book Test Slot →</a></div><div class="info-banner info-banner-plain"><span class="info-banner-icon" aria-hidden="true">ℹ</span><div><strong>Note:</strong> Please save/print the receipt for your records.</div></div></div></section>`,

  preparation:step=>{const done=getState().tutorialComplete;return `<section class="page"><div class="wrap"><nav class="breadcrumb"><a href="#/dashboard">Home</a> › <a href="#/dashboard">Learner Licence</a> › <a href="#/start">Apply for Learner Licence</a> › <span>Book Test Slot</span></nav><div class="page-header-block"><h1>Book Test Slot</h1><div class="app-num-chip">Application Number: <strong>${d.application.number}</strong></div></div>${done?`<div class="success-banner"><div class="success-banner-icon">✓</div><div><strong>You’ve watched the Road Safety Tutorial</strong><span>Thank you! You can now book your Online Learner’s Licence test slot.</span></div><div class="success-banner-graphic" aria-hidden="true">🎬</div></div>`:`<div class="warning-banner"><div class="warning-banner-head"><div class="warning-icon" aria-hidden="true">⚠️</div><div><h2>Before you book your test slot, you must watch the Road Safety Video.</h2><p class="hint">As per the Motor Vehicles Rules, it is mandatory for all learners to watch this video.</p></div></div><div class="warning-features"><div class="warning-feature"><div class="warning-feature-icon">▶</div><div><strong>Watch the complete video</strong><span class="hint">Duration: 20:45 mins</span></div></div><div class="warning-feature"><div class="warning-feature-icon">↻</div><div><strong>You can watch it only once</strong><span class="hint">The video will not be replayed</span></div></div><div class="warning-feature"><div class="warning-feature-icon">🔒</div><div><strong>After completion, you will be able to book your test slot</strong></div></div></div><a class="button button-primary" href="#/tutorial" id="preparation-next" data-complete="20">▶ Watch Road Safety Video →</a></div>`}<div class="book-slot-card${done?'':' is-disabled'}"><h2>Book Your Test Slot</h2><p class="hint">Select your preferred day, date and time for the Online Learner’s Licence Test.</p><div class="book-slot-fields"><div class="field"><label>Select Day <span class="required">*</span></label><select><option>Select day</option><option>Monday</option><option>Tuesday</option><option>Wednesday</option><option>Thursday</option><option>Friday</option></select></div><div class="field"><label>Select Date <span class="required">*</span></label><select><option>Select date</option><option>${d.booking.date}</option><option>05/09/2026</option><option>06/09/2026</option></select></div><div class="field"><label>Select Time Slot <span class="required">*</span></label><select><option>Select time slot</option>${d.slots.map(s=>`<option>${s}</option>`).join('')}</select></div></div><div class="check-availability"><div class="info-banner info-banner-plain"><span class="info-banner-icon" aria-hidden="true">ℹ</span>Test slots are subject to availability. You can only book one slot at a time.</div>${done?`<a class="button button-primary" href="#/slots">🔍 Check Availability</a>`:`<button class="button button-primary" type="button" disabled>🔍 Check Availability</button>`}</div></div>${guidelinesCard()}<div class="note-banner"><div class="note-banner-icon" aria-hidden="true">ℹ</div><div><strong>Note:</strong> After completing the test, your result will be displayed immediately. If you pass, your Learner’s Licence will be issued.</div></div></div></section>`},

  tutorial:step=>{const done=getState().tutorialComplete;return `<section class="page"><div class="wrap"><nav class="breadcrumb"><a href="#/dashboard">Home</a> › <a href="#/dashboard">Learner Licence</a> › <a href="#/start">Apply for Learner Licence</a> › <span>Road Safety Tutorial</span></nav><div class="page-header-block"><h1>Road Safety Tutorial</h1><p class="lede">Please watch the mandatory safety video completely before proceeding to your Learner’s License test.</p></div><div class="tutorial-lang"><label for="lang-select">Select Language</label><select id="lang-select"><option>English</option><option>Hindi</option><option>Tamil</option><option>Telugu</option></select></div><div class="tutorial-layout"><div class="tutorial-video-side"><div class="tutorial-video" id="video-box"><div class="tutorial-video-fallback"><strong>ROAD SAFETY</strong><span>Stay Alert, Stay Safe!</span></div><div class="tutorial-play" id="tutorial-play"></div><div class="tutorial-video-controls"><span id="tutorial-time">00:00 / 20:45</span><div class="tutorial-video-progress"><span id="video-progress"></span></div></div></div>${done?`<div class="watch-complete"><div class="warning-feature-icon" style="background:#28a745;color:#fff">✓</div><div><strong>You have watched the complete video.</strong><span>You can now book your test slot.</span></div></div>`:`<div class="watch-info"><span class="info-banner-icon" aria-hidden="true">ℹ</span><div>You can only book your test slot after you have watched this complete video.<br>The video will not be replayed.</div></div>`}</div><div class="tutorial-side-column"><div class="tutorial-side-card"><h2>Key Topics</h2><ul class="tutorial-topics"><li><div class="tutorial-topic-icon">🚦</div>Understanding Traffic Signals &amp; Signs</li><li><div class="tutorial-topic-icon">⏱️</div>Speed Limits and Safe Distances</li><li><div class="tutorial-topic-icon">🚶</div>Pedestrian Safety and Right of Way</li><li><div class="tutorial-topic-icon">⚠️</div>Handling Emergency Situations</li></ul></div><div class="status-block${done?' is-complete':''}"><div class="label">STATUS</div><div class="value">${done?'Completed ✓':'Incomplete'}</div></div></div></div><label class="tutorial-ack"><input type="checkbox" id="tutorial-check"${done?'':' disabled'}${done?' checked':''}><span>I acknowledge that I have watched the safety tutorial completely. I understand the rules of the road and the safety guidelines presented. I am ready to proceed to the Learner’s License Test.</span></label><div class="form-cta"><a class="button button-secondary" href="#/preparation">← Back to Details</a><a class="button button-primary${done?'':' is-locked'}" href="#/slots" id="tutorial-next" data-complete="22">📅 Book LL Test</a></div></div></section>`},

  'tutorial-complete':step=>page({step,title:'Road safety tutorial completed',intro:'Your completion has been recorded. You can now book your online test.',content:`${status('success','Completed','Tutorial requirement completed','No action is needed here. This completion is linked to your application.')} ${card(`<h2>What you covered</h2><p>Traffic signs · safe speed · pedestrian safety · emergency handling</p>`)}${actions('tutorial','slots','Book test slot','tutorial-done')}`}),

  slots:step=>`<section class="page"><div class="wrap"><nav class="breadcrumb"><a href="#/dashboard">Home</a> › <a href="#/dashboard">Learner Licence</a> › <a href="#/start">Apply for Learner Licence</a> › <span>Book Test Slot</span></nav><div class="page-header-block header-with-chip"><h1>Book Test Slot</h1><div class="app-num-chip">Application Number: <strong>${d.application.number}</strong></div></div><div class="success-banner"><div class="success-banner-icon">✓</div><div><strong>You’ve watched the Road Safety Tutorial</strong><span>Thank you! You can now book your Online Learner’s Licence test slot.</span></div><div class="success-banner-graphic" aria-hidden="true">🎬</div></div><div class="book-slot-card"><h2>Select Your Test Slot</h2><p class="hint">Choose your preferred day, date and time for the Online Learner’s Licence Test.</p><div class="book-slot-fields"><div class="field"><label>Select Day <span class="required">*</span></label><select id="slot-day"><option>Monday</option><option>Tuesday</option><option>Wednesday</option><option>Thursday</option><option>Friday</option></select></div><div class="field"><label>Select Date <span class="required">*</span></label><select id="slot-date"><option>${d.booking.date}</option><option>05/09/2026</option><option>06/09/2026</option></select></div><div class="field"><label>Select Time Slot <span class="required">*</span></label><select id="slot-time">${d.slots.map(s=>`<option>${s}</option>`).join('')}</select></div></div><div class="selected-slot-box" id="slot-summary"><div class="selected-slot-icon">📅</div><div class="selected-slot-info"><strong>Selected Slot Summary</strong><span><strong>Date:</strong> <span id="summary-date">Monday, ${d.booking.date}</span></span><br><span><strong>Time:</strong> <span id="summary-time">${d.slots[1]||d.booking.time} (IST)</span></span></div><a class="button button-primary" href="#/slot-confirmed" id="slot-continue" data-complete="23">📅 Book Slot</a></div></div>${guidelinesCard()}<div class="note-banner"><div class="note-banner-icon" aria-hidden="true">ℹ</div><div><strong>Note:</strong> After completing the test, your result will be displayed immediately. If you pass, your Learner’s Licence will be issued.</div></div></div></section>`,

  'slot-confirmed':step=>`<section class="page"><div class="wrap"><nav class="breadcrumb"><a href="#/dashboard">Home</a> › <a href="#/dashboard">Learner Licence</a> › <a href="#/start">Apply for Learner Licence</a></nav><div class="page-header-block"><h1>Application for Learner’s Licence</h1><div class="app-num-chip">Application Number: <strong>${d.application.number}</strong></div></div>${journeyStepper(5,'Pending')}<div class="slot-confirmed-card"><div class="slot-confirmed-check">📅</div><h2>Slot Booking Confirmed!</h2><p class="lede">Your slot has been booked successfully.</p><div class="slot-details"><div class="slot-details-left"><p class="hint">Your slot has been booked for</p><div class="slot-details-row"><span aria-hidden="true">📅</span><span>Monday, ${d.booking.date}</span></div><div class="slot-details-row"><span aria-hidden="true">🕐</span><span>${getState().slot||d.booking.time} (IST)</span></div></div><div class="slot-details-right"><p class="hint">Time Remaining</p><div class="countdown" id="countdown"><div class="countdown-cell"><strong>23</strong><span>HRS</span></div><div class="countdown-sep">:</div><div class="countdown-cell"><strong>59</strong><span>MINS</span></div><div class="countdown-sep">:</div><div class="countdown-cell"><strong>59</strong><span>SECS</span></div></div><p class="hint">Please take your test within the time limit.</p></div></div></div><div class="take-test-banner"><div class="take-test-copy"><strong>Please log in at least 10 minutes before your test time.</strong><span class="hint">Ensure you have a stable internet connection and a working webcam.</span></div><a class="button button-primary" href="#/instructions" id="slot-done" data-complete="24">🖥 Take the Online Test</a></div>${guidelinesCard()}<div class="review-card"><div class="review-card-head"><h3>What’s Next?</h3></div><div class="review-card-body"><div class="whats-next-grid"><div class="whats-next-item"><div class="whats-next-icon">📅</div><div><strong>Take the Online Test</strong><span class="hint">Appear for the online test on the scheduled date and time.</span></div></div><div class="whats-next-item"><div class="whats-next-icon">🪪</div><div><strong>Get your Learner’s Licence</strong><span class="hint">Once you pass the test, your Learner’s Licence will be issued.</span></div></div><div class="whats-next-item"><div class="whats-next-icon">🖨</div><div><strong>Print/Download Licence</strong><span class="hint">Download and print your Learner’s Licence for future use.</span></div></div></div></div></div><div class="note-banner"><div class="note-banner-icon" aria-hidden="true">ℹ</div><div><strong>Note:</strong> Please log in and take the test within the time limit. If you pass, your Learner’s Licence will be issued.</div></div></div></section>`,

  roadmap:step=>page({step,title:'Your application roadmap',intro:'See what is complete, what needs action, and what happens next.',wide:true,content:`${status('warning','Action required','Take your online test',`Your confirmed slot is ${d.booking.date} at ${getState().slot||d.booking.time}. Face authentication happens first.`)}${roadmap(step)}${card(`<h2>Appointment</h2><p><strong>${d.booking.date} · ${getState().slot||d.booking.time}</strong></p><p>Online from this device. No RTO visit is currently required. If face verification cannot be resolved online, we will explain the alternative.</p>`)}${actions('slot-confirmed','instructions','Start online test','roadmap-next')}`}),

  instructions:step=>page({step,title:'Online test instructions',intro:'Read these rules before starting. Your progress is not affected until the test begins.',content:`${card(`<h2>Before you start</h2><ul><li>Allow camera access for identity confirmation.</li><li>Sit in a well-lit place with your face clearly visible.</li><li>You will answer 15 questions in 10 minutes.</li><li>You need at least 60% to pass.</li><li>If your connection drops, return within 5 minutes to resume.</li></ul>`)}${status('info','Saved and ready','Your application is safe','A failed face check will not erase your payment, documents or booked slot.')}${actions('roadmap','face','Continue to face check','instructions-next')}`}),

  face:step=>`<section class="page"><div class="wrap"><nav class="breadcrumb"><a href="#/dashboard">Home</a> › <a href="#/dashboard">Learner Licence</a> › <span>Take Online LL Test</span></nav><div class="page-header-block"><h1>Take Online LL Test</h1></div>${testStepper(2)}<div class="face-layout"><div class="face-panel-left"><div class="app-num-card"><div class="app-num-icon">📄</div><div><div class="hint">Application Number</div><strong>${d.application.number}</strong></div></div><div class="face-panel-body"><h2 class="step-heading">Face Authentication</h2><p>We are scanning your face to verify your identity.<br>Please follow the instructions carefully.</p><div class="instructions-box"><strong>Please ensure that:</strong><ol class="numbered-list"><li><span class="num-badge">1</span>You are in a well-lit area</li><li><span class="num-badge">2</span>Your face is clearly visible</li><li><span class="num-badge">3</span>You are not wearing a mask or sunglasses</li><li><span class="num-badge">4</span>Only you are in the frame</li></ol></div><div class="attempts-info"><span class="attempts-icon" aria-hidden="true">ⓘ</span><span><strong>Maximum 3 attempts</strong> for face authentication. After that you will be required to upload your photo.</span></div></div></div><div class="face-panel-right"><div class="camera-panel"><div class="camera-panel-head"><span class="camera-status"><span class="dot"></span>Camera Access</span><span class="camera-cam-icon" aria-hidden="true">📷</span></div><p class="hint camera-substatus">Your camera is active</p><div class="camera-frame"><div class="camera-face" aria-hidden="true">😊</div><div class="camera-corners"><span class="corner tl"></span><span class="corner tr"></span><span class="corner bl"></span><span class="corner br"></span><div class="camera-oval"></div></div><div class="camera-overlay"><div class="scan-dot"></div><div><strong>Scanning your face…</strong><span>Please stay still</span></div></div></div></div></div></div><div class="cta-block"><div class="cta-copy"><span class="cta-icon" aria-hidden="true">ⓘ</span><div><strong>Having trouble?</strong><span>Ensure your camera is connected and working properly.</span></div></div><button class="button button-secondary" type="button" id="refresh-camera">🔄 Refresh Camera</button></div><div class="form-cta face-cta"><a class="button button-secondary" href="#/instructions">← Back to Test Details</a><div class="face-cta-actions"><a class="button button-primary" href="#/face-success" id="face-button" data-complete="27">Continue →</a><button class="button button-danger" type="button" id="face-fail-btn">Simulate Failure →</button></div></div></div></section>`,

  'face-failed':step=>{const attempts=(getState().faceAttempts||0)+1;const remaining=Math.max(0,3-attempts);return `<section class="page"><div class="wrap"><nav class="breadcrumb"><a href="#/dashboard">Home</a> › <a href="#/dashboard">Learner Licence</a> › <span>Take Online LL Test</span></nav><div class="page-header-block"><h1>Take Online LL Test</h1></div>${testStepper(2)}<div class="face-layout"><div class="face-panel-left"><div class="app-num-card"><div class="app-num-icon">📄</div><div><div class="hint">Application Number</div><strong>${d.application.number}</strong></div></div><div class="face-panel-body"><h2 class="step-heading">Face Authentication</h2><p>We are scanning your face to verify your identity.<br>Please follow the instructions carefully.</p><div class="fail-alert"><div class="fail-alert-head"><span class="fail-alert-icon" aria-hidden="true">⚠</span><strong>Authentication Failed</strong><span class="pill pill-fail">Attempt ${attempts} of 3</span></div><p>We couldn’t clearly verify your face.<br>This could be due to poor lighting, face not clearly visible, or looking away.</p></div><div class="fix-list"><h3><span class="fix-icon" aria-hidden="true">💡</span>How to fix it?</h3><ul><li>Move to a well-lit area (prefer natural light)</li><li>Avoid facing bright light or window from behind</li><li>Look straight at the camera</li><li>Ensure your entire face is within the frame</li><li>Remove any hair covering your face</li></ul></div><div class="warning-yellow"><span class="warning-yellow-icon" aria-hidden="true">📋</span><div><strong>Still having trouble?</strong> After 3 failed attempts, you will need to upload a clear photo of your face for verification.</div></div><div class="help-blue"><span class="help-blue-icon" aria-hidden="true">ⓘ</span><div><strong>Need Help?</strong><span>If the issue persists, please contact our support team.</span><a href="#" id="contact-support">Contact Support ↗</a></div></div></div></div><div class="face-panel-right"><div class="camera-panel"><div class="camera-panel-head"><span class="camera-status is-fail"><span class="dot"></span>Camera Access</span><span class="camera-cam-icon" aria-hidden="true">📷</span></div><p class="hint camera-substatus">Authentication failed. Please try again.</p><div class="camera-frame is-fail"><div class="camera-tip"><span aria-hidden="true">💡</span> Try a better lighting</div><div class="camera-face" aria-hidden="true">😐</div><div class="camera-corners"><span class="corner tl"></span><span class="corner tr"></span><span class="corner bl"></span><span class="corner br"></span><div class="camera-oval dashed"></div></div><div class="camera-overlay is-fail"><span aria-hidden="true">⚠</span><div><strong>Authentication Failed</strong><span>Attempt ${attempts} of 3</span></div></div></div><div class="face-retry-row"><div><strong>Want to try again?</strong><span class="hint">You have ${remaining} more attempts remaining.</span></div><a class="button button-secondary" href="#/face" id="face-retry">🔄 Retry</a></div></div></div></div><div class="stacked-card whatnext-card"><div class="section-block"><h3 class="whatnext-title"><span aria-hidden="true">ⓘ</span>What happens next?</h3><ol class="whatnext-flow">${['📄|Attempt 2|Try again to verify your identity.','📄|Attempt 3|You have 1 more attempt if needed.','🖼|Upload Photo|If all 3 attempts fail, you will be asked to upload a photo.','📋|Manual Review|Our team will review and verify your photo.','🛡|Continue Test|Once verified, you can proceed with the test.'].map((s,i,arr)=>{const [icon,title,desc]=s.split('|');const arrow=i<arr.length-1?'<span class="wf-arrow" aria-hidden="true">→</span>':'';return `<li><div class="wf-icon">${icon}</div><div class="wf-body"><strong>${title}</strong><span class="hint">${desc}</span></div></li>${arrow}`}).join('')}</ol></div></div><div class="cta-block"><div class="cta-copy"><span class="cta-icon" aria-hidden="true">ⓘ</span>Ensure your camera is connected and working properly.</div><button class="button button-primary" type="button" id="refresh-camera">🔄 Refresh Camera</button></div><div class="form-cta"><a class="button button-secondary" href="#/instructions">← Back to Test Details</a></div></div></section>`},

  'face-success':step=>page({step,title:'Face authentication successful',intro:'Your identity is confirmed for this test session.',content:`${status('success','Completed','Identity confirmed','The face check was recorded. You can begin the timed demo question now.')} ${card(`<h2>Before the timer starts</h2><p>The full service would show 15 questions. This prototype demonstrates one representative question and then lets you explore both result states.</p>`)}${actions('face','test','Begin test','face-done')}`}),

  test:step=>{const totalQ=15;const currentQ=8;const percent=Math.round(currentQ/totalQ*100);const overview=Array.from({length:totalQ},(_,i)=>{const n=i+1;const s=n<currentQ?'answered':n===currentQ?'current':'unanswered';return `<div class="overview-cell is-${s}">${n}</div>`}).join('');return `<section class="page test-page"><div class="wrap"><nav class="breadcrumb"><a href="#/dashboard">Home</a> › <a href="#/dashboard">Learner Licence</a> › <span>Take Online LL Test</span></nav><div class="page-header-block header-with-chip"><div><h1>Online Learner’s Licence Test</h1><p class="hint">Read the question carefully and choose the correct answer.</p></div><button class="button button-danger button-outline" type="button" id="end-test">↩ End Test</button></div><div class="test-layout"><div class="test-question-card"><div class="test-progress-row"><strong>QUESTION ${currentQ} OF ${totalQ}</strong><span class="test-progress-percent">${percent}% COMPLETED</span></div><div class="test-progress-bar"><span style="width:${percent}%"></span></div><div class="traffic-sign-box"><div class="traffic-sign" aria-hidden="true"><div class="triangle"><span>${d.question.sign}</span></div></div></div><h2 class="question-text">${escapeHtml(d.question.text)}</h2><div class="question-options">${d.question.options.map(option=>`<label class="test-choice"><input type="radio" name="answer" value="${escapeHtml(option)}"><span>${escapeHtml(option)}</span></label>`).join('')}</div><div id="test-message" aria-live="assertive"></div><div class="question-nav"><button class="button button-secondary" type="button" id="prev-question">← Previous Question</button><button class="button button-primary" id="submit-answer" type="button">Next Question →</button></div></div><aside class="test-sidebar"><div class="side-card"><h3><span aria-hidden="true">🛡</span>Test Guidelines</h3><ul class="side-guidelines"><li><span class="side-tick">✓</span>Do not refresh or close the window</li><li><span class="side-tick">✓</span>Do not switch to other browser tabs or windows</li><li><span class="side-tick">✓</span>Your screen is being recorded</li><li><span class="side-tick">✓</span>Ensure good lighting and stay in frame</li><li><span class="side-tick">✓</span>Maintain a stable internet connection</li></ul></div><div class="side-card"><h3>Live Proctoring</h3><div class="proctor-video" aria-hidden="true"><span class="proctor-rec">● REC</span><div class="proctor-fallback">👩‍💻</div></div><div class="proctor-verified"><span class="verified-badge">✓ Verified</span><span class="hint">You are being monitored</span></div></div><div class="side-card"><h3>Test Overview</h3><div class="overview-legend"><span class="legend-item"><span class="legend-dot is-answered"></span>Answered</span><span class="legend-item"><span class="legend-dot is-current"></span>Current</span><span class="legend-item"><span class="legend-dot is-unanswered"></span>Not Answered</span></div><div class="overview-grid">${overview}</div></div></aside></div><div class="cta-block need-help"><div class="cta-copy"><span class="cta-icon" aria-hidden="true">ⓘ</span><div><strong>Need Help?</strong><span class="hint">If you face any technical issue during the test, contact our support team immediately.</span></div></div><a href="#" class="info-link" id="test-support">Contact Support ↗</a></div></div></section>`},

  passed:step=>`<section class="page"><div class="wrap"><nav class="breadcrumb"><a href="#/dashboard">Home</a> › <a href="#/dashboard">Learner Licence</a> › <a href="#/instructions">Take Online LL Test</a> › <span>Test Result</span></nav><div class="result-card is-passed"><div class="result-check is-green">✓</div><h1 class="cong-title">Congratulations! You Passed! <span aria-hidden="true">🎉</span></h1><p>You have successfully completed the Online Learner’s Licence Test.</p><div class="score-tile"><div class="score-left"><div class="score-icon" aria-hidden="true">📋</div><div><span class="hint">You answered</span><strong class="score-big">9 <span class="hint">/ 15</span></strong><span class="hint">questions correctly</span></div></div><div class="score-right"><span class="hint">FINAL SCORE</span><strong class="score-percent is-pass">60%</strong><span class="pill pill-success">✓ PASSED</span></div></div><div class="result-actions"><button class="button button-secondary" type="button" id="licence-download">⬇ Download Learner’s Licence</button><button class="button button-secondary" type="button" id="print-receipt">🖨 Print Receipt</button></div><div class="result-affirmation"><span aria-hidden="true">✓</span><span>Your performance has been recorded successfully. Keep learning and drive safely!</span></div></div><div class="stacked-card whats-next-timeline-card"><div class="section-block"><h3>What Happens Next?</h3><ol class="whats-next-timeline">${[{icon:'🪪',title:'Learner’s Licence Issued',desc:'Your Learner’s Licence is now valid for 6 months across India.',state:'complete'},{icon:'●',title:'Practice Period',desc:'You must practice driving for at least <strong>30 days</strong> before applying for a Permanent Licence.<br>An ‘L’ board must be displayed on your vehicle while driving.',state:'current'},{icon:'📅',title:'Apply for Permanent Licence',desc:'Between day 31 and month 6, book a slot for your physical driving test at your local RTO to obtain your permanent Driving Licence.',state:'pending'}].map((s,i)=>`<li class="tl-${s.state}"><div class="tl-icon">${s.icon}</div><div class="tl-body"><strong>${s.title}</strong><p>${s.desc}</p></div><span class="tl-num">${i+1}</span></li>`).join('')}</ol></div></div><div class="stacked-card"><div class="section-block keep-in-mind"><div class="kim-head"><span class="kim-icon" aria-hidden="true">💡</span><strong>Keep These in Mind</strong></div><div class="kim-grid"><div><span class="kim-item-icon">🛡</span><span>Drive safely and responsibly always.</span></div><div><span class="kim-item-icon">📖</span><span>Keep learning the rules of the road.</span></div><div><span class="kim-item-icon">🚗</span><span>Practice regularly to build confidence.</span></div><div><span class="kim-item-icon">👥</span><span>Follow traffic rules for your safety and others.</span></div></div></div></div><p class="hint" style="text-align:center;margin-top:var(--space-4)">You can now view your application status and next steps.</p><div style="display:flex;justify-content:center;margin-top:var(--space-3)"><a class="button button-primary" href="#/licence" id="passed-next" data-complete="31">📋 View Application</a></div></div></section>`,

  'not-passed':step=>{const topics=['A zebra crossing is meant for:','What does a continuous white line mean?','Before changing lanes, you should:','Using a mobile phone while driving is:'];return `<section class="page"><div class="wrap"><nav class="breadcrumb"><a href="#/dashboard">Home</a> › <a href="#/dashboard">Learner Licence</a> › <a href="#/instructions">Take Online LL Test</a> › <span>Test Result</span></nav><div class="result-card is-failed"><div class="result-check is-red">✗</div><h1 class="cong-title is-red">Not quite there yet</h1><p>You scored 4 out of 15. Review the safety module and try<br>the test again when you are ready.</p><div class="score-tile"><div class="score-left"><div class="score-icon is-red" aria-hidden="true">📋</div><div><span class="hint">YOU ANSWERED</span><strong class="score-big is-red">4 <span class="hint">/ 15</span></strong><span class="hint">questions correctly</span></div></div><div class="score-right"><span class="hint">FINAL SCORE</span><strong class="score-percent is-fail">35%</strong><span class="pill pill-fail">✗ FAILED</span></div></div></div><div class="info-banner"><span class="info-banner-icon" aria-hidden="true">ⓘ</span><div><strong>Review the road-safety module to strengthen your knowledge.</strong><span class="hint">You can retry the test anytime when you feel prepared.</span></div><a class="button button-secondary" href="#/tutorial">📖 Review Module</a></div><div class="stacked-card"><div class="section-block"><h3>Review Before Retry</h3><p class="hint">Topics to revisit</p><ul class="review-list">${topics.map(t=>`<li class="review-list-item"><span class="review-icon">!</span><div><strong>${escapeHtml(t)}</strong><span class="hint">Review the road-safety module before trying again.</span></div><span class="review-chevron">›</span></li>`).join('')}</ul></div></div><div class="info-card info-card--tips"><h2>What’s Next?</h2><div class="whats-next-grid"><div class="whats-next-item"><div class="whats-next-icon">📖</div><div><strong>Review the Road-Safety Module</strong><span class="hint">Go through the road-safety module to build your understanding.</span></div></div><div class="whats-next-item"><div class="whats-next-icon">📋</div><div><strong>Practice More</strong><span class="hint">Take more mock tests to improve your score.</span></div></div><div class="whats-next-item"><div class="whats-next-icon">⚡</div><div><strong>Retry When Ready</strong><span class="hint">You can retry the test anytime when you feel confident.</span></div></div></div></div><p class="hint" style="text-align:center;margin-top:var(--space-4)">You can book a test slot again once you are ready.</p><div style="display:flex;justify-content:center;margin-top:var(--space-3)"><button class="button button-primary" type="button" id="retest-button">📅 Book LL Slot</button></div></div></section>`},

  licence:step=>`<section class="page"><div class="wrap"><nav class="breadcrumb"><a href="#/dashboard">Home</a> › <a href="#/dashboard">Learner Licence</a> › <span>Application Status</span></nav><div class="approved-card"><div class="approved-left"><div class="approved-check">✓</div><div><h1>Application Approved</h1><p>Your Learner’s Licence has been issued successfully.</p></div></div><div class="approved-graphic" aria-hidden="true"><div class="card-graphic"><span class="card-star">★</span></div></div></div>${journeyStepper(6,'Completed')}<section class="licence-card-new"><div class="licence-header"><span><strong>📋 Learner’s Licence</strong></span><span class="pill pill-success">VALID</span></div><div class="licence-body-new"><div class="licence-photo"><div class="portrait-large" aria-label="Applicant portrait">🧑</div><div class="qr-code" aria-hidden="true">▦ <span>Scan Me</span></div></div><div class="licence-details-grid"><div><span class="hint">Licence Number</span><strong>${escapeHtml(d.licence.number)}</strong></div><div><span class="hint">Applicant Name</span><strong>${escapeHtml(d.applicant.name)}</strong></div><div><span class="hint">Date of Birth</span><strong>${escapeHtml(d.applicant.dob)}</strong></div><div><span class="hint">Blood Group</span><strong>${escapeHtml(d.applicant.bloodGroup)}</strong></div><div class="span-2"><span class="hint">Vehicle Classes</span><div class="vehicle-tags"><span class="vehicle-tag">MCWG (Motor Cycle With Gear)</span><span class="vehicle-tag">LMV (Light Motor Vehicle)</span></div></div><div><span class="hint">Issue Date</span><strong>${escapeHtml(d.licence.validFrom)}</strong></div><div><span class="hint">Valid Till</span><strong>${escapeHtml(d.licence.validUntil)}</strong></div></div><div class="licence-watermark" aria-hidden="true">🚗</div></div></section><div class="licence-actions"><button class="button button-secondary" type="button" id="print-doc">🖨 Print Document</button><button class="button button-secondary" type="button" id="save-digilocker">⬇ Save to DigiLocker</button><button class="button button-secondary" type="button" id="share-licence">↗ Share Licence</button></div><div class="next-step-banner"><div class="next-step-icon" aria-hidden="true">📅</div><div class="next-step-copy"><strong>Next Step: Driving Licence</strong><span class="hint">You can apply for a Driving Licence after 30 days from the date of issue of Learner’s Licence.</span></div><button class="button button-primary" type="button" id="apply-dl">Apply for Driving Licence →</button></div><div class="stacked-card"><div class="section-block"><h3>Application Summary</h3><div class="app-summary-grid"><div><span class="hint">Application Number</span><strong>${escapeHtml(d.application.number)}</strong></div><div><span class="hint">Applied On</span><strong>24 May 2025</strong></div><div><span class="hint">RTO Office</span><strong>MH-01 Mumbai (South)</strong></div><div><span class="hint">Fee Paid</span><strong>₹350.00</strong></div><div><span class="hint">Payment Status</span><span class="pill pill-success">Paid</span></div></div></div></div></div></section>`
};

/** Persists the chosen state and moves the user to the dashboard. */
function bindWelcome(){const select=document.querySelector('#welcome-state-select');const button=document.querySelector('#welcome-continue');if(!select||!button)return;button.addEventListener('click',()=>{if(!select.value){select.focus();toast('Please select a state to continue.');return}saveState({selectedState:select.value});completeStep(1);toast(`State saved: ${select.value}.`);window.location.hash='#/dashboard'})}

/** Wires the demo-only actions on the service dashboard. */
function bindDashboard(){
  const trackBtn=document.querySelector('#track-btn');const trackInput=document.querySelector('#track-input');
  if(trackBtn)trackBtn.addEventListener('click',()=>{const val=(trackInput&&trackInput.value.trim())||'';toast(val?`Demo lookup for ${val} would run here.`:'Enter your application number to check status.')});
  const where=document.querySelector('#where-app-num');if(where)where.addEventListener('click',e=>{e.preventDefault();toast('Your application number was shown on the payment success screen.')});
  const applyDl=document.querySelector('#apply-dl-btn');if(applyDl)applyDl.addEventListener('click',e=>{e.preventDefault();toast('The Driving Licence flow is represented but outside this prototype.')});
  const help=document.querySelector('#help-center-btn');if(help)help.addEventListener('click',()=>document.querySelector('#help-dialog').showModal());
  const guide=document.querySelector('#doc-guidelines');if(guide)guide.addEventListener('click',e=>{e.preventDefault();window.location.hash='#/documents'});
  const viewAll=document.querySelector('#view-all-notifs');if(viewAll)viewAll.addEventListener('click',e=>{e.preventDefault();toast('All demo notifications are shown here.')});
}

/** Simulates OTP verification, auto-advance between boxes, resend, and countdown. */
function bindOtp(){
  processLink('otp-continue','test-type','Verifying code…');
  const resend=document.querySelector('#resend-otp');if(resend)resend.addEventListener('click',e=>{e.preventDefault();toast(`A new demo code was sent. Use ${d.applicant.otp}.`)});
  const change=document.querySelector('#change-mobile');if(change)change.addEventListener('click',e=>{e.preventDefault();toast('The mobile number is fixed for this demo.')});
  const boxes=[...document.querySelectorAll('[data-otp-index]')];
  boxes.forEach((box,i)=>{
    box.addEventListener('input',()=>{if(box.value&&boxes[i+1])boxes[i+1].focus()});
    box.addEventListener('keydown',e=>{if(e.key==='Backspace'&&!box.value&&boxes[i-1])boxes[i-1].focus()});
  });
  const timerEl=document.querySelector('#otp-timer');if(timerEl){let secs=45;const t=setInterval(()=>{secs-=1;if(secs<=0){clearInterval(t);timerEl.textContent='00:00'}else timerEl.textContent=`00:${String(secs).padStart(2,'0')}`},1000)}
}

/** Placeholder handlers on the start screen. */
function bindStart(){
  const find=document.querySelector('#find-rto');if(find)find.addEventListener('click',e=>{e.preventDefault();toast('An RTO locator would open here.')});
}

/** Placeholder handler for the verification-methods learn-more link. */
function bindIdentity(){
  const learn=document.querySelector('#learn-more-verif');if(learn)learn.addEventListener('click',e=>{e.preventDefault();toast('Verification method guidance would open here.')});
}

/** Copies present-address fields into permanent-address fields when the box is ticked. */
function bindAddress(){
  const check=document.querySelector('#same-address');if(!check)return;
  const pairs=[['preState','permState'],['preDistrict','permDistrict'],['preTehsil','permTehsil'],['preTown','permTown'],['preHouse','permHouse'],['preStreet','permStreet'],['preArea','permArea'],['prePincode','permPincode']];
  check.addEventListener('change',()=>{if(!check.checked)return;pairs.forEach(([src,dst])=>{const s=document.querySelector(`[name="${src}"]`);const d=document.querySelector(`[name="${dst}"]`);if(s&&d){d.value=s.value;d.dispatchEvent(new Event('input',{bubbles:true}))}});toast('Permanent address copied from present address.')});
}

/** Declaration: Form1 toast + block continue until fitness declaration ticked. */
function bindDeclaration(){
  const form1=document.querySelector('#form1-btn');if(form1)form1.addEventListener('click',()=>toast('Form1 (Self-Declaration) would open here in the full service.'));
  const fitness=document.querySelector('#fitness-check');const next=document.querySelector('#declaration-continue');
  if(!fitness||!next)return;
  next.addEventListener('click',e=>{if(!fitness.checked){e.preventDefault();fitness.focus();toast('Please tick the Declaration of Fitness before continuing.')}});
}

/** Expands or collapses document cards; edit-details is a placeholder toast. */
function bindDocuments(){
  document.querySelectorAll('[data-doc-toggle]').forEach(btn=>btn.addEventListener('click',()=>{const card=btn.closest('[data-doc-card]');if(card)card.classList.toggle('is-expanded')}));
  document.querySelectorAll('[data-edit-doc]').forEach(btn=>btn.addEventListener('click',()=>toast('The edit dialog for this document would open here.')));
}

/** Blocks Confirm & Submit until the review declaration is ticked. */
function bindReview(){
  const check=document.querySelector('#review-declaration');const next=document.querySelector('#review-submit');
  if(!check||!next)return;
  next.addEventListener('click',e=>{if(!check.checked){e.preventDefault();check.focus();toast('Please read and accept the declaration before submitting.')}});
}

/** Simulates the payment call, plus print-receipt toast on the success screen. */
function bindPayment(){
  processLink('pay-button','payment-success','Processing your payment…',{paymentComplete:true});
  processLink('confirm-payment','payment-success','Confirming transaction…',{paymentComplete:true});
  const print=document.querySelector('#print-receipt');if(print)print.addEventListener('click',()=>toast(`Demo receipt ${d.payment.transaction} would be printed here. No real file is generated.`));
  const receipt=document.querySelector('#receipt-button');if(receipt)receipt.addEventListener('click',()=>toast(`Demo receipt ${d.payment.transaction} is ready. No real file is generated.`));
}

/** Simulates the 20:45 video: play button starts a fake 8s playback, then unlocks the acknowledgement + Book LL Test button. */
function bindTutorial(){
  const play=document.querySelector('#tutorial-play');const bar=document.querySelector('#video-progress');const time=document.querySelector('#tutorial-time');const check=document.querySelector('#tutorial-check');const next=document.querySelector('#tutorial-next');const status=document.querySelector('.status-block');const info=document.querySelector('.watch-info');
  const finish=()=>{if(check){check.disabled=false;check.checked=true}if(next){next.classList.remove('is-locked')}if(status){status.classList.add('is-complete');const v=status.querySelector('.value');if(v)v.textContent='Completed ✓'}if(info){info.className='watch-complete';info.innerHTML=`<div class="warning-feature-icon" style="background:#28a745;color:#fff">✓</div><div><strong>You have watched the complete video.</strong><span>You can now book your test slot.</span></div>`}saveState({tutorialComplete:true});toast('Tutorial marked as watched.')};
  if(getState().tutorialComplete){if(next)next.classList.remove('is-locked');if(bar)bar.style.width='100%';if(time)time.textContent='20:45 / 20:45'}
  else if(next){next.classList.add('is-locked');next.addEventListener('click',e=>{if(!check||!check.checked){e.preventDefault();toast('Play the short demo tutorial, then tick the acknowledgement.')}})}
  if(play&&!getState().tutorialComplete){play.addEventListener('click',()=>{play.style.display='none';let secs=0;const total=8;const timer=setInterval(()=>{secs+=1;if(bar)bar.style.width=`${(secs/total)*100}%`;if(time)time.textContent=`${String(Math.floor(secs*20.5/total)).padStart(2,'0')}:${String(Math.floor((secs*20.5/total*60)%60)).padStart(2,'0')} / 20:45`;if(secs>=total){clearInterval(timer);if(time)time.textContent='20:45 / 20:45';finish()}},500)},{once:true})}
}

/** Preparation: enables the disabled slot-selection form when the tutorial has been watched. */
function bindPreparation(){
  const next=document.querySelector('#preparation-next');if(next&&getState().tutorialComplete)toast('You’ve already watched the tutorial. Continue to book a slot.');
}

/** Countdown timer for the Slot Booking Confirmed screen. */
function bindSlotConfirmed(){
  const box=document.querySelector('#countdown');if(!box)return;
  const cells=box.querySelectorAll('.countdown-cell strong');if(cells.length<3)return;
  const target=Date.now()+(23*3600+59*60+59)*1000;
  const tick=()=>{const remaining=Math.max(0,target-Date.now());const hrs=Math.floor(remaining/3600000);const mins=Math.floor((remaining%3600000)/60000);const secs=Math.floor((remaining%60000)/1000);cells[0].textContent=String(hrs).padStart(2,'0');cells[1].textContent=String(mins).padStart(2,'0');cells[2].textContent=String(secs).padStart(2,'0');if(remaining>0)setTimeout(tick,1000)};tick();
}

/** Book Test Slot form: mirrors day/date/time dropdowns into the summary box and stores the selected time. */
function bindSlots(){
  const day=document.querySelector('#slot-day');const date=document.querySelector('#slot-date');const time=document.querySelector('#slot-time');const summaryDate=document.querySelector('#summary-date');const summaryTime=document.querySelector('#summary-time');
  const update=()=>{if(summaryDate&&day&&date)summaryDate.textContent=`${day.value}, ${date.value}`;if(summaryTime&&time)summaryTime.textContent=`${time.value} (IST)`;if(time)saveState({slot:time.value})};
  [day,date,time].forEach(el=>el&&el.addEventListener('change',update));
  if(time)saveState({slot:time.value});
}

/** Face auth demo: Continue simulates success, Simulate Failure sends to the failed branch. */
function bindFace(){
  const cont=document.querySelector('#face-button');if(cont)cont.addEventListener('click',e=>{e.preventDefault();setLoading(cont,'Verifying face…');setTimeout(()=>{saveState({faceAttempts:0});window.location.hash='#/face-success'},1600)});
  const fail=document.querySelector('#face-fail-btn');if(fail)fail.addEventListener('click',()=>{const attempts=(getState().faceAttempts||0)+1;saveState({faceAttempts:attempts});window.location.hash='#/face-failed'});
  const refresh=document.querySelector('#refresh-camera');if(refresh)refresh.addEventListener('click',()=>toast('Camera refreshed (simulated). Please wait for the scan to restart.'));
  const retry=document.querySelector('#face-retry');if(retry)retry.addEventListener('click',()=>toast('Retrying face verification…'));
  const contact=document.querySelector('#contact-support');if(contact)contact.addEventListener('click',e=>{e.preventDefault();toast('Support chat would open here.')});
}

/** Validates the demo test answer and exposes both result branches; End Test bails out to instructions. */
function bindTest(){
  const button=document.querySelector('#submit-answer');if(!button)return;
  document.querySelectorAll('.question-options .test-choice').forEach(choice=>choice.addEventListener('click',()=>{const input=choice.querySelector('input');if(input)input.checked=true}));
  button.addEventListener('click',()=>{const selected=document.querySelector('input[name="answer"]:checked');if(!selected){toast('Choose an answer before submitting.');return}setLoading(button,'Recording answer…');setTimeout(()=>{const passed=selected.value===d.question.answer;saveState({testResult:passed?'passed':'not-passed'});window.location.hash=passed?'#/passed':'#/not-passed'},1500)});
  const prev=document.querySelector('#prev-question');if(prev)prev.addEventListener('click',()=>toast('This demo shows a single question. Try the answer to continue.'));
  const end=document.querySelector('#end-test');if(end)end.addEventListener('click',()=>{if(window.confirm('End the test now? Your progress will be discarded.'))window.location.hash='#/instructions'});
  const support=document.querySelector('#test-support');if(support)support.addEventListener('click',e=>{e.preventDefault();toast('Support chat would open here.')});
}

/** Makes the retest recovery path immediately explorable in the prototype. */
function bindRetake(){const btn=document.querySelector('#retest-button');if(btn)btn.addEventListener('click',()=>{saveState({slot:''});toast('Retest eligibility simulated. Choose a new slot to continue.');setTimeout(()=>{window.location.hash='#/slots'},800)})}

/** Passed-screen buttons: represent the demo actions as toasts. */
function bindPassed(){
  const dl=document.querySelector('#licence-download');if(dl)dl.addEventListener('click',()=>toast(`Demo licence ${d.licence.number} would be downloaded here.`));
  const print=document.querySelector('#print-receipt');if(print)print.addEventListener('click',()=>toast(`Receipt ${d.payment.transaction} would be printed here.`));
}

/** Licence-page actions: print, DigiLocker save, share, and Driving Licence CTA are demo toasts. */
function bindDownload(){
  const dl=document.querySelector('#licence-download');if(dl)dl.addEventListener('click',()=>toast(`Demo licence ${d.licence.number} is represented on screen; no valid document is generated.`));
  const print=document.querySelector('#print-doc');if(print)print.addEventListener('click',()=>toast('Demo licence would be printed here.'));
  const digi=document.querySelector('#save-digilocker');if(digi)digi.addEventListener('click',()=>toast('The DigiLocker integration would run here.'));
  const share=document.querySelector('#share-licence');if(share)share.addEventListener('click',()=>toast('Sharing options would open here.'));
  const dl2=document.querySelector('#apply-dl');if(dl2)dl2.addEventListener('click',()=>toast('The Driving Licence flow is out of scope for this prototype.'));
}
